import React from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import './SinglePhoto.css';

const SinglePhoto = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const { photo, alt, eventName } = location.state || {};

  React.useEffect(() => {
    if (!photo) navigate('/portfolio');
  }, [photo, navigate]);

  if (!photo) return null;

  const handleDownload = () => {
    const link = document.createElement('a');
    link.href = photo;
    link.download = photo.split('/').pop();
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="single-photo-bg">
      <div className="single-photo-header">
        <h1>{eventName || 'Event Photo'}</h1>
        <button className="single-photo-back" onClick={() => navigate(-1)}>← Back to Gallery</button>
      </div>
      <div className="single-photo-viewer">
        <img src={photo} alt={alt} className="single-photo-img" />
        <button className="single-photo-download-btn" onClick={handleDownload}>Download</button>
      </div>
    </div>
  );
};

export default SinglePhoto;
